content:
:root {
  --color-primary: #2563eb;
  --color-primary-hover: #1d4ed8;
  --color-primary-light: #eff6ff;
  --color-text-main: #1e293b;
  --color-text-muted: #64748b;
  --color-text-light: #94a3b8;
  --color-bg-page: #f8fafc;
  --color-bg-card: #ffffff;
  --color-border: #e2e8f0;
  --color-border-light: #f1f5f9;
  --color-row-hover: #f8fafc;
  --color-row-alt: #fafafa;
  --color-badge-bg: #e0f2fe;
  --color-badge-text: #0369a1;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -2px rgba(0, 0, 0, 0.1);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -4px rgba(0, 0, 0, 0.1);
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", "Hiragino Sans", "Hiragino Kaku Gothic ProN", "Yu Gothic", sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  background-color: var(--color-bg-page);
  color: var(--color-text-main);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

.app-container {
  min-height: 100vh;
  padding: 32px 16px;
  display: flex;
  justify-content: center;
  align-items: flex-start;
}

.card {
  width: 100%;
  max-width: 900px;
  background-color: var(--color-bg-card);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-md);
  border: 1px solid var(--color-border);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  gap: 20px;
  padding: 28px;
}

.header {
  border-bottom: 1px solid var(--color-border-light);
  padding-bottom: 16px;
}

.title {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--color-text-main);
  letter-spacing: -0.02em;
}

.subtitle {
  font-size: 0.875rem;
  color: var(--color-text-muted);
  margin-top: 4px;
}

.search-section {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.search-box {
  position: relative;
  display: flex;
  align-items: center;
  flex: 1 1 280px;
  max-width: 400px;
}

.search-icon {
  position: absolute;
  left: 12px;
  width: 18px;
  height: 18px;
  color: var(--color-text-light);
  pointer-events: none;
  display: flex;
  align-items: center;
  justify-content: center;
}

.search-input {
  width: 100%;
  height: 40px;
  padding: 8px 36px 8px 38px;
  font-size: 0.9375rem;
  color: var(--color-text-main);
  background-color: #ffffff;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.search-input:focus {
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.15);
}

.search-input::placeholder {
  color: var(--color-text-light);
}

.clear-btn {
  position: absolute;
  right: 10px;
  background: none;
  border: none;
  color: var(--color-text-light);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 4px;
  border-radius: 50%;
  font-size: 0.875rem;
  line-height: 1;
  transition: color 0.15s ease, background-color 0.15s ease;
}

.clear-btn:hover {
  color: var(--color-text-main);
  background-color: var(--color-border-light);
}

.result-count {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-text-muted);
  white-space: nowrap;
}

.result-count strong {
  color: var(--color-primary);
  font-weight: 700;
}

.table-wrapper {
  width: 100%;
  overflow-x: auto;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  background-color: #ffffff;
}

.employee-table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
  font-size: 0.9375rem;
}

.employee-table th,
.employee-table td {
  padding: 14px 18px;
  border-bottom: 1px solid var(--color-border-light);
}

.employee-table th {
  background-color: #f8fafc;
  color: var(--color-text-muted);
  font-weight: 600;
  font-size: 0.8125rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  user-select: none;
  white-space: nowrap;
}

.th-sortable {
  cursor: pointer;
  transition: background-color 0.15s ease, color 0.15s ease;
}

.th-sortable:hover {
  background-color: #f1f5f9;
  color: var(--color-text-main);
}

.th-content {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.sort-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 16px;
  height: 16px;
  color: var(--color-text-light);
  transition: transform 0.15s ease, color 0.15s ease;
}

.sort-active {
  color: var(--color-primary);
  font-weight: 700;
}

.sort-active .sort-icon {
  color: var(--color-primary);
}

.employee-table tbody tr {
  transition: background-color 0.15s ease;
}

.employee-table tbody tr:hover {
  background-color: var(--color-row-hover);
}

.employee-table tbody tr:last-child td {
  border-bottom: none;
}

.badge {
  display: inline-flex;
  align-items: center;
  padding: 4px 10px;
  border-radius: 9999px;
  font-size: 0.8125rem;
  font-weight: 600;
  line-height: 1.2;
}

.badge-dept {
  background-color: var(--color-badge-bg);
  color: var(--color-badge-text);
  border: 1px solid rgba(3, 105, 161, 0.15);
}

.age-cell {
  font-variant-numeric: tabular-nums;
  font-weight: 500;
  color: var(--color-text-main);
}

.empty-state {
  text-align: center;
  padding: 48px 16px;
  color: var(--color-text-muted);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
}

.empty-state p {
  font-size: 0.9375rem;
}

.reset-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 16px;
  background-color: var(--color-primary);
  color: #ffffff;
  border: none;
  border-radius: var(--radius-md);
  font-size: 0.875rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.15s ease, transform 0.05s ease;
}

.reset-btn:hover {
  background-color: var(--color-primary-hover);
}

.reset-btn:active {
  transform: translateY(1px);
}

@media (max-width: 640px) {
  .app-container {
    padding: 16px 8px;
  }

  .card {
    padding: 16px;
    border-radius: var(--radius-md);
  }

  .title {
    font-size: 1.25rem;
  }

  .search-section {
    flex-direction: column;
    align-items: stretch;
  }

  .search-box {
    max-width: 100%;
  }

  .employee-table th,
  .employee-table td {
    padding: 10px 12px;
  }
}

export interface Employee {
  id: number;
  name: string;
  department: string;
  age: number;
}

export type SortField = 'name' | 'department' | 'age';

export type SortOrder = 'asc' | 'desc';

export interface SortConfig {
  field: SortField;
  order: SortOrder;
}

import { Employee } from './types';

export const INITIAL_EMPLOYEES: Employee[] = [
  {
    id: 1,
    name: '佐藤 健一',
    department: '営業部',
    age: 28,
  },
  {
    id: 2,
    name: '田中 美咲',
    department: '開発部',
    age: 24,
  },
  {
    id: 3,
    name: '鈴木 翔太',
    department: '開発部',
    age: 34,
  },
  {
    id: 4,
    name: '高橋 優子',
    department: '人事部',
    age: 41,
  },
  {
    id: 5,
    name: '渡辺 大輔',
    department: '企画部',
    age: 31,
  },
  {
    id: 6,
    name: '伊藤 奈々',
    department: '営業部',
    age: 26,
  },
  {
    id: 7,
    name: '山本 拓也',
    department: '総務部',
    age: 52,
  },
  {
    id: 8,
    name: '中村 葵',
    department: '開発部',
    age: 29,
  },
  {
    id: 9,
    name: '小林 誠',
    department: '企画部',
    age: 46,
  },
  {
    id: 10,
    name: '加藤 直樹',
    department: '総務部',
    age: 38,
  },
];

import { useState, useMemo } from 'react';
import { ArrowUpDown, ArrowUp, ArrowDown, Search, X, RotateCcw } from 'lucide-react';
import { SortField, SortConfig } from './types';
import { INITIAL_EMPLOYEES } from './data';
import './index.css';

export default function App() {
  const [searchQuery, setSearchQuery] = useState<string>('');
  const [sortConfig, setSortConfig] = useState<SortConfig>({
    field: 'name',
    order: 'asc',
  });

  const handleSort = (field: SortField) => {
    setSortConfig((prev) => {
      if (prev.field === field) {
        return {
          field,
          order: prev.order === 'asc' ? 'desc' : 'asc',
        };
      }
      return {
        field,
        order: 'asc',
      };
    });
  };

  const handleClearSearch = () => {
    setSearchQuery('');
  };

  const handleReset = () => {
    setSearchQuery('');
    setSortConfig({ field: 'name', order: 'asc' });
  };

  const filteredAndSortedEmployees = useMemo(() => {
    const trimmedQuery = searchQuery.trim().toLowerCase();

    const filtered = INITIAL_EMPLOYEES.filter((emp) => {
      if (!trimmedQuery) return true;
      return emp.name.toLowerCase().includes(trimmedQuery);
    });

    return [...filtered].sort((a, b) => {
      const { field, order } = sortConfig;
      let comparison = 0;

      if (field === 'age') {
        comparison = a.age - b.age;
      } else if (field === 'name') {
        comparison = a.name.localeCompare(b.name, 'ja');
      } else if (field === 'department') {
        comparison = a.department.localeCompare(b.department, 'ja');
      }

      return order === 'asc' ? comparison : -comparison;
    });
  }, [searchQuery, sortConfig]);

  const renderSortIcon = (field: SortField) => {
    if (sortConfig.field !== field) {
      return (
        <span className="sort-icon" aria-hidden="true">
          <ArrowUpDown size={14} />
        </span>
      );
    }

    return (
      <span className="sort-icon" aria-hidden="true">
        {sortConfig.order === 'asc' ? <ArrowUp size={14} /> : <ArrowDown size={14} />}
      </span>
    );
  };

  return (
    <div className="app-container">
      <main className="card">
        <header className="header">
          <h1 className="title">社員名簿一覧</h1>
          <p className="subtitle">社員情報の確認、名前による絞り込み検索および各列の並べ替えが可能です</p>
        </header>

        <section className="search-section" aria-label="検索と件数表示">
          <div className="search-box">
            <span className="search-icon" aria-hidden="true">
              <Search size={18} />
            </span>
            <input
              type="text"
              className="search-input"
              placeholder="社員名で検索..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              aria-label="社員名で検索"
            />
            {searchQuery && (
              <button
                type="button"
                className="clear-btn"
                onClick={handleClearSearch}
                aria-label="検索キーワードをクリア"
              >
                <X size={16} />
              </button>
            )}
          </div>

          <div className="result-count">
            該当社員: <strong>{filteredAndSortedEmployees.length}</strong> / {INITIAL_EMPLOYEES.length} 名
          </div>
        </section>

        <div className="table-wrapper">
          {filteredAndSortedEmployees.length > 0 ? (
            <table className="employee-table">
              <thead>
                <tr>
                  <th
                    scope="col"
                    className={`th-sortable ${sortConfig.field === 'name' ? 'sort-active' : ''}`}
                    onClick={() => handleSort('name')}
                    aria-sort={
                      sortConfig.field === 'name'
                        ? sortConfig.order === 'asc'
                          ? 'ascending'
                          : 'descending'
                        : 'none'
                    }
                  >
                    <div className="th-content">
                      <span>氏名</span>
                      {renderSortIcon('name')}
                    </div>
                  </th>
                  <th
                    scope="col"
                    className={`th-sortable ${sortConfig.field === 'department' ? 'sort-active' : ''}`}
                    onClick={() => handleSort('department')}
                    aria-sort={
                      sortConfig.field === 'department'
                        ? sortConfig.order === 'asc'
                          ? 'ascending'
                          : 'descending'
                        : 'none'
                    }
                  >
                    <div className="th-content">
                      <span>部署</span>
                      {renderSortIcon('department')}
                    </div>
                  </th>
                  <th
                    scope="col"
                    className={`th-sortable ${sortConfig.field === 'age' ? 'sort-active' : ''}`}
                    onClick={() => handleSort('age')}
                    aria-sort={
                      sortConfig.field === 'age'
                        ? sortConfig.order === 'asc'
                          ? 'ascending'
                          : 'descending'
                        : 'none'
                    }
                  >
                    <div className="th-content">
                      <span>年齢</span>
                      {renderSortIcon('age')}
                    </div>
                  </th>
                </tr>
              </thead>
              <tbody>
                {filteredAndSortedEmployees.map((employee) => (
                  <tr key={employee.id}>
                    <td>{employee.name}</td>
                    <td>
                      <span className="badge badge-dept">{employee.department}</span>
                    </td>
                    <td className="age-cell">{employee.age} 歳</td>
                  </tr>
                ))}
              </tbody>
            </table>
          ) : (
            <div className="empty-state">
              <p>「{searchQuery}」に一致する社員は見つかりませんでした。</p>
              <button type="button" className="reset-btn" onClick={handleReset}>
                <RotateCcw size={16} />
                検索条件をリセット
              </button>
            </div>
          )}
        </div>
      </main>
    </div>
  );
}
